FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    location    "system";
    object      decomposeParDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

numberOfSubdomains 4; // 8; // this is number of proc


method         scotch; // automatic

simpleCoeffs // not auto
{
    n               ( 4 1 1 );
    delta           0.001;
}

distributed     no;

roots           ( );


